fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Rook moves:
    // 0 if same square,
    // 1 if same row or same column,
    // otherwise 2.
    let rook = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop moves:
    // 0 if same square,
    // 1 if on the same diagonal,
    // 2 if same color but not same diagonal,
    // 0 if different color (unreachable).
    let bishop = if r1 == r2 && c1 == c2 {
        0
    } else if (r1 - r2).abs() == (c1 - c2).abs() {
        1
    } else {
        // check same color by parity of (row + col)
        let color1 = (r1 + c1) & 1;
        let color2 = (r2 + c2) & 1;
        if color1 == color2 {
            2
        } else {
            0
        }
    };

    // King moves: Chebyshev distance
    let king = std::cmp::max((r1 - r2).abs(), (c1 - c2).abs());

    vec![rook, bishop, king]
}